import Image from "next/image";
import Link from "next/link";
import { cn } from "@/lib/utils";

type LogoProps = {
  href?: string | null;
  className?: string;
  /** Rendered height in px — width follows the artwork ratio (2.44 : 1). */
  height?: number;
  priority?: boolean;
  /** Adds the soft neumorphic plate behind the mark. */
  plate?: boolean;
};

/**
 * The Ceyteq lockup. `public/brand/ceyteq-logo.png` is generated by
 * `scripts/prepare-logo.mjs`, which removes the photographed white paper
 * background and exposes a real alpha channel, so the mark blends straight
 * into the ash neumorphic surface.
 */
export function Logo({ href = "/", className, height = 40, priority, plate }: LogoProps) {
  const image = (
    <Image
      src="/brand/ceyteq-logo.png"
      alt="Ceyteq — Empowering Digital Evolution"
      height={height}
      width={Math.round(height * 2.38)}
      priority={priority}
      className={cn(
        "w-auto select-none object-contain drop-shadow-[0_6px_14px_rgba(8,43,73,0.14)]",
        className,
      )}
      style={{ height }}
    />
  );

  const content = plate ? (
    <span className="neu inline-flex items-center rounded-2xl px-4 py-2.5">{image}</span>
  ) : (
    image
  );

  if (!href) return content;
  return (
    <Link href={href} aria-label="Ceyteq Digital Race home" className="inline-flex shrink-0">
      {content}
    </Link>
  );
}

export function LogoMark({ size = 40, className }: { size?: number; className?: string }) {
  return (
    <Image
      src="/brand/ceyteq-mark.svg"
      alt=""
      width={size}
      height={size}
      aria-hidden
      className={cn("object-contain", className)}
      style={{ width: size, height: size }}
    />
  );
}
